package com.aiservice.infrastructure.persistence.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="textbook_structure_drafts") public class TextbookStructureDraftEntity{@Id public UUID id;@Column(name="subject_id",nullable=false)public UUID subjectId;@Column(name="owner_id",nullable=false)public UUID ownerId;@Column(name="original_file_name",nullable=false)public String originalFileName;@Column(name="storage_key",nullable=false)public String storageKey;@Column(nullable=false)public String status;@Column(name="extracted_text",nullable=false,columnDefinition="TEXT")public String extractedText;@Column(name="structure_json",nullable=false,columnDefinition="TEXT")public String structureJson;@Column(name="processing_error",length=1000)public String processingError;@Column(name="created_at",nullable=false)public Instant createdAt;@Column(name="updated_at",nullable=false)public Instant updatedAt;}
